// mini-md — a tiny hand-rolled Markdown renderer for comment boxes.
//
// Security model:
//   1. Every piece of user text is HTML-escaped BEFORE any markup is built
//      around it, so `<img onerror=...>`, `<script>`, etc. can never become
//      real elements.
//   2. Link hrefs must pass an allowlist (http:, https:, mailto:, or schemeless
//      relative URLs). Anything else — javascript:, data:, unknown schemes —
//      leaves the whole `[text](url)` construct as plain escaped text.
//   3. The allowlist probe strips whitespace/control characters from the URL
//      before scheme detection, because browsers strip tab/LF/CR out of
//      attribute values ("jav\tascript:" parses as "javascript:").
//   4. Every emitted anchor gets rel="noopener noreferrer" target="_blank".

/**
 * Escape a string for safe interpolation into HTML text content or a
 * double-quoted attribute value.
 */
export function escapeHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const SAFE_SCHEMES = new Set(['http:', 'https:', 'mailto:']);

/**
 * Decide whether a raw link target may be used as an href.
 * Allows http:, https:, mailto: and relative URLs (including protocol-relative
 * "//" and root-relative "/"). Rejects anything with a foreign scheme.
 */
export function isSafeUrl(rawUrl) {
  if (typeof rawUrl !== 'string') return false;
  // Browsers strip tab/newline/CR (and other control chars) from URLs before
  // parsing, so probe a copy with them removed.
  const probe = rawUrl.replace(/[\u0000-\u0020\u007f]+/g, '');
  const schemeMatch = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(probe);
  if (!schemeMatch) {
    // No scheme at all -> relative (covers "", "/", "foo/bar", "../x", "//host/x")
    return true;
  }
  return SAFE_SCHEMES.has(schemeMatch[1].toLowerCase());
}

// Placeholder sentinels for spans that are already fully-rendered HTML and
// must survive the final escape pass untouched. Control chars never appear in
// normal input, and even if they did they would be inert text.
const PH = { code: '\u0000', link: '\u0001' };
function stash(store, marker, html) {
  store.push(html);
  return `${marker}${store.length - 1}${marker}`;
}
function unstash(text, store, marker) {
  return text.replace(
    new RegExp(`${marker}(\\d+)${marker}`, 'g'),
    (_, i) => store[Number(i)]
  );
}

/** Render inline constructs: `code`, [text](url), **bold**, *italic*. */
export function renderInline(raw) {
  // Already-safe fragments (inline code, anchors) are stashed so the blanket
  // escape pass below cannot touch them.
  const stash_ = [];

  // Inline code first — its contents are literal, no further markup inside.
  let text = raw.replace(/`([^`\n]+)`/g, (_, code) =>
    stash(stash_, PH.code, `<code>${escapeHtml(code)}</code>`)
  );

  // Links. Unsafe targets (javascript:, data:, ...) are left in place and end
  // up rendered as plain escaped text by the pass below.
  text = text.replace(/\[([^\]\n]*)\]\(([^()\n]*)\)/g, (_, label, url) => {
    if (!isSafeUrl(url)) return _;
    return stash(
      stash_,
      PH.link,
      `<a href="${escapeHtml(url)}" rel="noopener noreferrer" target="_blank">${escapeHtml(label)}</a>`
    );
  });

  // Blanket-escape everything that is still plain user text.
  text = escapeHtml(text);

  // Emphasis on the escaped text (asterisks are unaffected by escaping).
  text = text.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>');
  text = text.replace(/\*([^*\n]+)\*/g, '<em>$1</em>');

  text = unstash(text, stash_, PH.link);
  return unstash(text, stash_, PH.code);
}

const FENCE_RE = /^\s*```/;
const FENCE_CLOSE_RE = /^\s*```\s*$/;
const LIST_ITEM_RE = /^\s*[-*+]\s+(.*)$/;

/**
 * Render a Markdown subset to an HTML string.
 * Supports: paragraphs, **bold**, *italic*, `inline code`, ``` fenced code
 * blocks ```, [links](url), and unordered lists.
 */
export function renderMarkdown(src) {
  const lines = String(src).replace(/\r\n?/g, '\n').split('\n');
  const out = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // Fenced code block: contents are literal, escaped-only.
    if (FENCE_RE.test(line)) {
      const lang = line.trim().slice(3).trim();
      i++;
      const buf = [];
      while (i < lines.length && !FENCE_CLOSE_RE.test(lines[i])) {
        buf.push(lines[i]);
        i++;
      }
      i++; // consume closing fence (or hit EOF)
      const cls = lang ? ` class="language-${escapeHtml(lang)}"` : '';
      out.push(`<pre><code${cls}>${escapeHtml(buf.join('\n'))}</code></pre>`);
      continue;
    }

    // Unordered list.
    const item = LIST_ITEM_RE.exec(line);
    if (item) {
      const items = [];
      while (i < lines.length) {
        const m = LIST_ITEM_RE.exec(lines[i]);
        if (!m) break;
        items.push(`<li>${renderInline(m[1])}</li>`);
        i++;
      }
      out.push(`<ul>${items.join('')}</ul>`);
      continue;
    }

    if (line.trim() === '') {
      i++;
      continue;
    }

    // Paragraph: consecutive non-blank lines until blank line / fence / list.
    const buf = [line];
    i++;
    while (
      i < lines.length &&
      lines[i].trim() !== '' &&
      !FENCE_RE.test(lines[i]) &&
      !LIST_ITEM_RE.test(lines[i])
    ) {
      buf.push(lines[i]);
      i++;
    }
    out.push(`<p>${buf.map(renderInline).join('<br>')}</p>`);
  }

  return out.join('\n');
}

