import { describe, it, expect } from 'vitest';
import { parse } from 'node-html-parser';
import { renderMarkdown, isSafeUrl, escapeHtml } from './render.js';

// ---- helpers -----------------------------------------------------------

/** Parse rendered HTML and collect every node + attribute in the tree. */
function audit(html) {
  const root = parse(html);
  const nodes = [];
  const attrs = [];
  (function walk(node) {
    for (const child of childNodesOf(node)) {
      if (child.nodeType === 1) {
        nodes.push(child);
        for (const [name, value] of Object.entries(child.attributes ?? {})) {
          attrs.push({ name, value, tag: child.rawTagName });
        }
      }
      walk(child);
    }
  })(root);
  return { root, nodes, attrs, html };
}

function childNodesOf(node) {
  return node.childNodes ?? [];
}

function tags(nodes) {
  return new Set(nodes.map((n) => n.rawTagName?.toLowerCase()));
}

function attrNames(attrs) {
  return new Set(attrs.map((a) => a.name.toLowerCase()));
}

/**
 * The core sanitization invariant: no script/img (or other dangerous)
 * elements anywhere, and no event-handler (`on*`) attribute anywhere.
 */
function assertSanitized(html) {
  const { nodes, attrs, root } = audit(html);
  const seen = tags(nodes);
  expect(seen).not.toContain('script');
  expect(seen).not.toContain('img');
  expect(seen).not.toContain('iframe');
  expect(seen).not.toContain('svg');
  expect(seen).not.toContain('object');
  expect(seen).not.toContain('embed');
  for (const a of attrs) {
    expect(a.name.toLowerCase()).not.toMatch(/^on/i);
  }
  // No javascript:/data: href sneaks through after entity decoding.
  for (const a of attrs) {
    if (a.name.toLowerCase() === 'href' || a.name.toLowerCase() === 'src') {
      const v = (a.value ?? '').replace(/[\s\u0000-\u0020]/g, '').toLowerCase();
      expect(v.startsWith('javascript:')).toBe(false);
      expect(v.startsWith('data:')).toBe(false);
      expect(v.startsWith('vbscript:')).toBe(false);
    }
  }
  void root;
}

// ---- structure tests per construct --------------------------------------

describe('paragraphs', () => {
  it('wraps plain text in <p>', () => {
    const html = renderMarkdown('hello world');
    expect(html).toBe('<p>hello world</p>');
    const p = parse(html).querySelector('p');
    expect(p?.text).toBe('hello world');
  });

  it('joins consecutive lines and splits on blank lines', () => {
    const html = renderMarkdown('one\ntwo\n\nthree');
    expect(parse(html).querySelectorAll('p')).toHaveLength(2);
    expect(parse(html).querySelectorAll('br')).toHaveLength(1);
  });

  it('emits nothing for empty input', () => {
    expect(renderMarkdown('')).toBe('');
  });
});

describe('bold', () => {
  it('renders **text** as <strong>', () => {
    const html = renderMarkdown('this is **bold** text');
    const strong = parse(html).querySelector('strong');
    expect(strong).not.toBeNull();
    expect(strong.text).toBe('bold');
    expect(parse(html).querySelector('p').innerHTML).toBe(
      'this is <strong>bold</strong> text'
    );
  });
});

describe('italics', () => {
  it('renders *text* as <em>', () => {
    const html = renderMarkdown('this is *italic* text');
    const em = parse(html).querySelector('em');
    expect(em).not.toBeNull();
    expect(em.text).toBe('italic');
  });

  it('keeps bold and italic independent', () => {
    const html = renderMarkdown('**b** and *i*');
    expect(parse(html).querySelector('strong').text).toBe('b');
    expect(parse(html).querySelector('em').text).toBe('i');
  });
});

describe('inline code', () => {
  it('renders `code` as <code>', () => {
    const html = renderMarkdown('run `npm test` now');
    const code = parse(html).querySelector('p > code');
    expect(code).not.toBeNull();
    expect(code.text).toBe('npm test');
  });

  it('suppresses markup inside inline code', () => {
    const html = renderMarkdown('`**not bold**`');
    expect(parse(html).querySelector('code').text).toBe('**not bold**');
    expect(html).not.toContain('<strong>');
  });
});

describe('fenced code blocks', () => {
  it('wraps fenced content in pre > code', () => {
    const html = renderMarkdown('```\nlet x = 1;\n```');
    const pre = parse(html).querySelector('pre');
    expect(pre).not.toBeNull();
    expect(pre.querySelector('code')).not.toBeNull();
    expect(pre.querySelector('code').text).toContain('let x = 1;');
  });

  it('captures the info string as a language class', () => {
    const html = renderMarkdown('```js\nconst a = 2;\n```');
    const code = parse(html).querySelector('pre > code');
