  const html = renderMarkdown('```\nlet x = 1;\n```');
  // node-html-parser models <pre> contents as raw text, so assert structure
  // on the emitted markup itself.
  expect(html).toMatch(/^<pre><code>let x = 1;<\/code><\/pre>$/);
});

